nav a.active { color: var(--accent); background: var(--accent-soft); font-weight: 600; }
main { padding: 28px 20px 40px; }
.hero { margin-bottom: 24px; }
.eyebrow { color: var(--accent); font-weight: 600; font-size: 13px; letter-spacing: 0.04em; text-transform: uppercase; margin: 0 0 6px; }
h1 { font-size: 34px; line-height: 1.15; margin: 0 0 10px; letter-spacing: -0.01em; }
h2 { font-size: 22px; margin: 0 0 6px; }
.lede { font-size: 17px; color: var(--muted); max-width: 640px; margin: 0; }
.intro { color: var(--muted); margin: 0 0 14px; max-width: 680px; }
section { margin: 36px 0; }
.kpis { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; margin: 8px 0; }
.kpi { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 16px; }
.kpi-value { font-size: 24px; font-weight: 700; letter-spacing: -0.01em; }
.kpi-label { font-weight: 600; margin-top: 2px; }
.kpi-sub { color: var(--muted); font-size: 13px; }
.kpi-src { color: var(--faint); font-size: 12px; margin-top: 6px; }
table { width: 100%; border-collapse: collapse; font-size: 15px; }
th, td { text-align: left; padding: 9px 10px; border-bottom: 1px solid var(--line); }
th { color: var(--muted); font-size: 13px; text-transform: uppercase; letter-spacing: 0.03em; }
td:first-child, th:first-child { padding-left: 0; }
.hbar-row { display: grid; grid-template-columns: 220px 1fr 130px; gap: 10px; align-items: center; padding: 7px 0; border-bottom: 1px solid var(--line); }
.hbar-label { font-size: 14px; }
.hbar-track { background: #f5f5f4; border-radius: 4px; height: 12px; overflow: hidden; }
.hbar-fill { display: block; height: 100%; background: var(--accent); border-radius: 4px; }
.hbar-value { text-align: right; font-weight: 600; font-size: 14px; }
.donut-wrap { display: flex; gap: 28px; align-items: center; background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 18px; flex-wrap: wrap; }
.legend-row { display: flex; gap: 8px; align-items: center; padding: 5px 0; font-size: 15px; }
.legend-row b { margin-left: auto; padding-left: 24px; }
.legend { min-width: 220px; flex: 1; }
.dot { width: 12px; height: 12px; border-radius: 50%; display: inline-block; }
.src-note { color: var(--faint); font-size: 13px; margin: 10px 0 0; }
.verdict { color: var(--muted); font-size: 14px; margin: 4px 0 10px; }
.planner-box { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 18px; }
.planner-box label { display: block; font-weight: 600; font-size: 14px; margin-bottom: 12px; }
.planner-box input { display: block; width: 100%; max-width: 320px; margin-top: 4px; padding: 9px 10px; font-size: 15px; border: 1px solid var(--line); border-radius: 8px; background: #fff; }
.split-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.pl-sum { font-weight: 600; }
.pl-sum.ok { color: var(--teal); }
.pl-sum.bad { color: #b91c1c; }
.ex-form { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 18px; }
.ex-form label { display: block; font-weight: 600; font-size: 14px; }
.ex-form input, .ex-form select { display: block; width: 100%; margin-top: 4px; padding: 9px 10px; font-size: 15px; border: 1px solid var(--line); border-radius: 8px; background: #fff; }
.ex-form button, .del { cursor: pointer; }
.ex-form button { grid-column: 1 / -1; justify-self: start; padding: 10px 18px; font-size: 15px; font-weight: 600; color: #fff; background: var(--accent); border: none; border-radius: 8px; }
.del { padding: 4px 10px; font-size: 13px; color: #b91c1c; background: none; border: 1px solid #fecaca; border-radius: 6px; }
a { color: var(--accent); }
footer { border-top: 1px solid var(--line); padding: 18px 20px 28px; color: var(--muted); font-size: 13px; }
@media (max-width: 640px) {
  h1 { font-size: 27px; }
  .kpis { grid-template-columns: 1fr 1fr; }
  .kpi-value { font-size: 19px; }
  .hbar-row { grid-template-columns: 120px 1fr 96px; }
  .hbar-value { font-size: 12px; }
  .ex-form { grid-template-columns: 1fr; }
  .split-row { grid-template-columns: 1fr 1fr 1fr; }
  table { font-size: 13px; }
  th, td { padding: 8px 6px; }
  .donut-wrap { justify-content: center; }
}
